type Speed = "1" | "3600" | "86400" | "2592000" | "31557600";
const YEAR_S = 31557600;
/* t150: 仿真时钟 = 距历元 JD_START 的儒略年数（1 年 = 365.25 日 = YEAR_S 秒），历元即 2026-11-01 16:00:00 UTC（与 JD_START 一致，已核对 JD=2461346.16667）。
   PREV: START_MS = new Date(2026, 10, 2, 0, 0, 0).getTime()（按浏览器本地时区、固定假起点）；fmtDate 用本地时间 getFullYear/getHours… */
const START_MS = Date.UTC(2026, 10, 1, 16, 0, 0);
/* 当前真实 UTC 对应的仿真年数（Date.now() 即 UTC 毫秒） */
function utcNowYears(): number {
  return (Date.now() - START_MS) / 1000 / YEAR_S;
}
function fmtDate(years: number): string {
  const d = new Date(START_MS + years * YEAR_S * 1000);
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getUTCFullYear()}/${p(d.getUTCMonth() + 1)}/${p(d.getUTCDate())} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())} UTC`;
}

