function galOrbitItems(g: GalMoon, parent: "jupiter" | "saturn" | "uranus" | "neptune" | "pluto" = "jupiter"): Item[] {
  const parentName = { jupiter: "木星 Jupiter", saturn: "土星 Saturn", uranus: "天王星 Uranus", neptune: "海王星 Neptune", pluto: "冥王星 Pluto" }[parent];
  return [
    { label: "类型", value: g.kind },
    { label: "轨道中心", value: `${parentName}（绕其赤道）` },
    { label: "平均轨道半径", value: `${f(g.aKm / 1000, 1)} 千公里（${f(g.aRj, 2)} × ${parentName}赤道半径）` },
    { label: "轨道偏心率", value: f(g.ecc, 3) },
    { label: "轨道倾角", value: `${f(g.inc, 2)}°（相对${parentName}赤道）` },
    { label: "公转周期", value: `${f(g.orbDays, 6)} 天（潮汐锁定）` },
    { label: "平均轨道速度", value: `${f(g.vel, 2)} km/s` },
    { label: `光传播时间（到${parentName}）`, value: `${f((g.aKm * 1000) / 299792458, 2)} 秒` },
  ];
}
/* 母行星（或冥王星系统）绕日公转周期（天），用于潮汐锁定卫星的太阳日 */
const MOON_PARENT_YEAR_D: Record<string, number> = {
  io: 4332.589,
  europa: 4332.589,
  ganymede: 4332.589,
  callisto: 4332.589,
  titan: 10755.699,
  titania: 30685.4,
  triton: 60189.018,
  charon: 90560,
};
function galPhysItems(g: GalMoon, rotH: number, id?: string): Item[] {
  const sense = rotH < 0 ? "逆行" : "顺行";
  const yD = id ? MOON_PARENT_YEAR_D[id] : undefined;
  /* 太阳日 = 1/(1/P_rot − 1/P_year)，P_rot 带符号（逆行为负） */
  const solarH = yD ? 1 / (1 / rotH - 1 / (yD * 24)) : null;
  return [
    {
      label: "平均半径",
      value: `${f(g.radius, 1)} km（地球 = ${ratio(g.radius / 6378.137)} · 月球 = ${ratio(g.radius / 1737.4)}）`,
    },
    {
      label: "质量",
      value: `${sci(g.mass20 * 1e20)} kg（地球 = ${ratio(g.mass20 * 1e20 / 5.9722e24)}）`,
    },
    {
      label: "平均密度",
      value: `${f(g.dens, 0)} kg/m³（地球 = ${f(g.dens / 5513, 2)}）`,
    },
    {
      label: "表面重力",
      value: `${f(g.grav, 3)} m/s²（${f(g.grav / 9.80665, 3)} g）`,
    },
    { label: "逃逸速度", value: `${f(g.esc, 3)} km/s` },
    {
      label: "自转周期",
      value: `${hfmt(rotH)} · ${sense} · 与公转同步（潮汐锁定）`,
    },
    ...(solarH !== null && isFinite(solarH) ? [{ label: "昼长（日出到日出）", value: hfmt(solarH) }] : []),
    {
      label: "平均温度",
      value: `${f(g.tC, 0)} °C（${f(g.tC + 273.15, 0)} K）· ${g.tNote}`,
    },
    { label: "表面气压", value: g.pres ?? "可忽略（近乎真空）" },
    { label: "几何反照率", value: f(g.albedo, 2) },
    { label: "行星环", value: "无" },
  ];
}

