const TW = 1024;
const TH = 512;
const CS = 480;
const TAU = Math.PI * 2;

function spinSeconds(rotH: number, mode: SpinMode): number {
  const a = Math.abs(rotH);
  return mode === "ratio" ? a / 3 : 8 * Math.pow(a / 23.9345, 0.35);
}
function secFmt(s: number): string {
  return s < 100 ? `${f(s, 1)} 秒` : `${f(s / 60, 1)} 分钟`;
}

function hash3(x: number, y: number, z: number): number {
  let h =
    (Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(z, 1274126177)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1103515245);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}
function vnoise(x: number, y: number, z: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const zi = Math.floor(z);
  const xf = x - xi;
  const yf = y - yi;
  const zf = z - zi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const w = zf * zf * (3 - 2 * zf);
  const a = hash3(xi, yi, zi);
  const b = hash3(xi + 1, yi, zi);
  const c = hash3(xi, yi + 1, zi);
  const d = hash3(xi + 1, yi + 1, zi);
  const e = hash3(xi, yi, zi + 1);
  const f2 = hash3(xi + 1, yi, zi + 1);
  const g = hash3(xi, yi + 1, zi + 1);
  const h2 = hash3(xi + 1, yi + 1, zi + 1);
  const x1 = a + (b - a) * u;
  const x2 = c + (d - c) * u;
  const x3 = e + (f2 - e) * u;
  const x4 = g + (h2 - g) * u;
  const y1 = x1 + (x2 - x1) * v;
  const y2 = x3 + (x4 - x3) * v;
  return y1 + (y2 - y1) * w;
}
function fbm(x: number, y: number, z: number, oct: number): number {
  let amp = 0.5;
  let sum = 0;
  let norm = 0;
  let fr = 1;
  for (let i = 0; i < oct; i++) {
    sum += amp * vnoise(x * fr + i * 17.3, y * fr - i * 9.1, z * fr + i * 3.7);
    norm += amp;
    amp *= 0.5;
    fr *= 2.03;
  }
  return sum / norm;
}
const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v);
const mix = (a: number, b: number, t: number): number => a + (b - a) * t;
const sstep = (a: number, b: number, v: number): number => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

type Spot = { x: number; y: number; z: number; r: number; cosO: number };

function makeSpots(count: number, seed0: number, rMin: number, rRange: number, latMax: number): Spot[] {
  let seed = seed0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  const out: Spot[] = [];
  for (let i = 0; i < count; i++) {
    const y = (rnd() * 2 - 1) * latMax;
    const phi = rnd() * TAU;
    const rr = Math.sqrt(1 - y * y);
    const r = rMin + rnd() * rnd() * rRange;
    out.push({ x: rr * Math.cos(phi), y, z: rr * Math.sin(phi), r, cosO: Math.cos(r * 1.3) });
  }
  return out;
}

function genTexture(id: string): { rgb: Uint8ClampedArray; aux: Uint8ClampedArray } {
  const rgb = new Uint8ClampedArray(TW * TH * 3);
  const aux = new Uint8ClampedArray(TW * TH);
  const craters =
    id === "mercury"
      ? makeSpots(95, 777, 0.015, 0.14, 1)
      : id === "moon"
        ? makeSpots(130, 991, 0.012, 0.12, 1)
        : [];
  const spots = id === "sun" ? makeSpots(9, 4242, 0.03, 0.05, 0.5) : [];
  for (let j = 0; j < TH; j++) {
    const lat = Math.PI / 2 - ((j + 0.5) / TH) * Math.PI;
    const cl = Math.cos(lat);
    const sl = Math.sin(lat);
    for (let i = 0; i < TW; i++) {
      const lon = ((i + 0.5) / TW) * TAU - Math.PI;
      const px = cl * Math.sin(lon);
      const py = sl;
      const pz = cl * Math.cos(lon);
      let r = 128;
      let g = 128;
      let b = 128;
      let a = 0;
      if (id === "mercury") {
        const n = fbm(px * 3 + 1, py * 3 + 2, pz * 3 + 3, 5);
        const m = fbm(px * 1.2 + 9, py * 1.2, pz * 1.2 - 4, 3);
        let sh = (0.62 + (n - 0.5) * 1.3) * (0.9 + (m - 0.5) * 0.5);
        for (let c = 0; c < craters.length; c++) {
          const cr = craters[c];
          const d = px * cr.x + py * cr.y + pz * cr.z;
          if (d > cr.cosO) {
            const t = Math.acos(Math.min(1, d)) / cr.r;
            if (t < 1) sh *= 0.78 + 0.22 * t;
            else sh *= 1 + 0.28 * (1 - (t - 1) / 0.3);
          }
        }
        r = 152 * sh;
        g = 143 * sh;
        b = 134 * sh;
      } else if (id === "moon") {
        const n = fbm(px * 4 + 2, py * 4 + 6, pz * 4 + 1, 5);
        const mm = sstep(0.5, 0.6, fbm(px * 1.5 + 11, py * 1.5, pz * 1.5 + 4, 4));
        let sh = (0.78 + (n - 0.5) * 0.9) * (1 - 0.42 * mm);
        for (let c = 0; c < craters.length; c++) {
          const cr = craters[c];
          const d = px * cr.x + py * cr.y + pz * cr.z;
          if (d > cr.cosO) {
            const t = Math.acos(Math.min(1, d)) / cr.r;
            if (t < 1) sh *= 0.8 + 0.2 * t;
            else sh *= 1 + 0.3 * (1 - (t - 1) / 0.3);
          }
        }
        r = 158 * sh;
        g = 156 * sh;
        b = 150 * sh;
      } else if (id === "venus") {
        const w = fbm(px * 2.2 + 4, py * 2.2, pz * 2.2 - 3, 5);
        const flow = fbm(px * 1.4, py * 3.5 + w * 2, pz * 1.4, 5);
        const uv =
          Math.exp(-Math.pow(lon / 0.9, 2)) * (1 - Math.abs(lat) * 0.7) * 0.55 +
          Math.exp(-Math.pow((lon + 0.2) / 1.4, 2)) * Math.abs(lat) * 0.45;
        const t = clamp(flow * 0.7 + w * 0.4, 0, 1);
        r = mix(230, 250, t);
        g = mix(205, 238, t);
        b = mix(150, 200, t);
        r = mix(r, 160, uv * 0.35);
        g = mix(g, 140, uv * 0.35);
        b = mix(b, 95, uv * 0.35);
      } else if (id === "earth") {
        const h = fbm(px * 1.7 + 5, py * 1.7 + 1, pz * 1.7 + 2, 6);
        const sea = 0.545;
        if (h < sea) {
          const d = clamp((sea - h) / 0.12, 0, 1);
          r = mix(52, 7, d);
          g = mix(120, 34, d);
          b = mix(180, 92, d);
        } else {
          const e = clamp((h - sea) / 0.14, 0, 1);
          const dry = sstep(
            0.5,
            0.7,
            fbm(px * 3 + 8, py * 3, pz * 3, 3) +
              0.25 * Math.exp(-Math.pow(Math.abs(lat) - 0.45, 2) / 0.05),
          );
          r = mix(58, 190, dry);
          g = mix(118, 160, dry);
          b = mix(52, 100, dry);
          const mt = sstep(0.4, 0.8, e);
          r = mix(r, 120, mt);
          g = mix(g, 100, mt);
          b = mix(b, 80, mt);
          const sn = sstep(0.85, 1, e);
          r = mix(r, 245, sn);
          g = mix(g, 245, sn);
          b = mix(b, 250, sn);
        }
        const iceLine = 1.22 + (fbm(px * 3 + 3, py * 3, pz * 3, 3) - 0.5) * 0.24;
        const ice = sstep(iceLine, iceLine + 0.06, Math.abs(lat));
        r = mix(r, 240, ice);
        g = mix(g, 245, ice);
        b = mix(b, 250, ice);
        const c = fbm(px * 2.6 + 20, py * 5.2 + 3, pz * 2.6, 5);
        a = clamp((c - 0.47) * 5.5, 0, 1) * 235;
      } else if (id === "mars") {
        const n = fbm(px * 2.4 + 3, py * 2.4 + 7, pz * 2.4 + 1, 5);
        const dark = sstep(0.5, 0.62, n);
        const fine = fbm(px * 9, py * 9, pz * 9, 3);
        const k = 0.88 + fine * 0.24;
        r = mix(198, 122, dark) * k;
        g = mix(106, 62, dark) * k;
        b = mix(60, 42, dark) * k;
        const iceLine = 1.33 + (fbm(px * 4, py * 4 + 5, pz * 4, 3) - 0.5) * 0.3;
        const ice = sstep(iceLine, iceLine + 0.05, Math.abs(lat));
        r = mix(r, 240, ice);
        g = mix(g, 240, ice);
        b = mix(b, 245, ice);
      } else if (id === "jupiter") {
        const wl = lat + (fbm(px * 4 + 2, py * 4, pz * 4 + 9, 5) - 0.5) * 0.14;
        const s =
          Math.sin(wl * 14) * 0.55 +
          Math.sin(wl * 28 + 0.9) * 0.25 +
          Math.sin(wl * 7) * 0.2 +
          Math.sin(wl * 46 + 2) * 0.12;
        const t = sstep(-0.7, 0.7, s);
        const fine = fbm(px * 2.5, py * 28, pz * 2.5, 4);
        const fil = fbm(px * 5, py * 60, pz * 5, 3);
        const k = 0.75 + fine * 0.3 + fil * 0.12;
        r = mix(110, 245, t) * k;
        g = mix(70, 220, t) * k;
        b = mix(45, 185, t) * k;
        const dl = Math.atan2(Math.sin(lon - 0.92), Math.cos(lon - 0.92));
        const dx = (dl * cl) / 0.28;
        const dy = (lat + 0.4) / 0.095;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d < 1.35) {
          const m = sstep(1.2, 0.35, d);
          r = mix(r, 205, m * 0.55);
          g = mix(g, 155, m * 0.55);
          b = mix(b, 125, m * 0.55);
        }
        const wo = Math.exp(-((lon + 1.55) * (lon + 1.55) / 0.04 + (lat + 0.28) * (lat + 0.28) / 0.01));
        r = mix(r, 248, wo * 0.55);
        g = mix(g, 242, wo * 0.55);
        b = mix(b, 230, wo * 0.55);
      } else if (id === "saturn") {
        const wl = lat + (fbm(px * 4 + 7, py * 4, pz * 4 + 1, 5) - 0.5) * 0.07;
        const s = Math.sin(wl * 12) * 0.45 + Math.sin(wl * 28 + 0.8) * 0.18 + Math.sin(wl * 48) * 0.08;
        const t = sstep(-0.55, 0.55, s);
        const fine = fbm(px * 2.5, py * 22, pz * 2.5, 4);
        const k = 0.95 + fine * 0.1;
        r = mix(205, 242, t) * k;
        g = mix(178, 224, t) * k;
        b = mix(130, 180, t) * k;
        const pole = sstep(1.2, 1.45, Math.abs(lat));
        r = mix(r, 190, pole * 0.35);
        g = mix(g, 188, pole * 0.35);
        b = mix(b, 175, pole * 0.35);
      } else if (id === "uranus") {
        const fine = fbm(px * 2, py * 10, pz * 2, 3);
        const k = 1 + 0.045 * Math.sin(lat * 11 + fine * 3) + (fine - 0.5) * 0.04;
        const t = 0.5 + 0.5 * Math.sin(lat * 3 - 0.4);
        r = mix(138, 178, t) * k;
        g = mix(206, 232, t) * k;
        b = mix(214, 236, t) * k;
      } else if (id === "neptune") {
        // Oxford 2024 / Voyager 真色：淡青绿/海蓝绿，非教材深蓝
        const wl = lat + (fbm(px * 3 + 5, py * 3, pz * 3, 3) - 0.5) * 0.08;
        const s = Math.sin(wl * 12) * 0.5 + 0.5;
        r = mix(110, 145, s);
        g = mix(175, 205, s);
        b = mix(185, 210, s);
        const dl = Math.atan2(Math.sin(lon - 0.55), Math.cos(lon - 0.55));
        const dx = (dl * cl) / 0.28;
        const dy = (lat + 0.32) / 0.14;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d < 1) {
          const m = sstep(1, 0.45, d);
          r = mix(r, 55, m * 0.7);
          g = mix(g, 90, m * 0.7);
          b = mix(b, 110, m * 0.7);
        }
        const n = fbm(px * 3, py * 14, pz * 3, 3);
        const w = sstep(0.72, 0.88, n) * (0.35 + 0.65 * Math.abs(lat));
        r = mix(r, 230, w * 0.55);
        g = mix(g, 245, w * 0.55);
        b = mix(b, 250, w * 0.55);
      } else if (id === "sun") {
        const gr = fbm(px * 26 + 1, py * 26 + 4, pz * 26 + 7, 3);
        const t = sstep(0.35, 0.7, gr);
        const m = fbm(px * 4 + 2, py * 4, pz * 4, 3);
        const k = 0.9 + (m - 0.5) * 0.4;
        r = mix(226, 255, t) * k;
        g = mix(84, 212, t) * k;
        b = mix(14, 92, t) * k;
        for (let c = 0; c < spots.length; c++) {
          const sp = spots[c];
          const d = px * sp.x + py * sp.y + pz * sp.z;
          if (d > sp.cosO) {
            const tt = Math.acos(Math.min(1, d)) / sp.r;
            const f3 = tt < 0.5 ? 0.2 : tt < 1 ? 0.2 + 0.5 * sstep(0.5, 1, tt) : 0.7 + 0.3 * sstep(1, 1.3, tt);
            r *= f3;
            g *= f3 * f3;
            b *= f3 * f3;
          }
        }
        a = clamp(fbm(px * 26 + 50, py * 26 + 44, pz * 26 + 31, 3) * 255, 0, 255);
      }
      const idx = j * TW + i;
      rgb[idx * 3] = r;
      rgb[idx * 3 + 1] = g;
      rgb[idx * 3 + 2] = b;
      aux[idx] = a;
    }
  }
  // Exact lon 0°/360° weld so Closeup nearest/bilinear never shows a vertical strip
  for (let j = 0; j < TH; j++) {
    const i0 = j * TW;
    const iN = i0 + TW - 1;
    for (let c = 0; c < 3; c++) {
      const m = (rgb[i0 * 3 + c] + rgb[iN * 3 + c]) >> 1;
      rgb[i0 * 3 + c] = m;
      rgb[iN * 3 + c] = m;
    }
    const am = (aux[i0] + aux[iN]) >> 1;
    aux[i0] = am;
    aux[iN] = am;
  }
  return { rgb, aux };
}

const TEX_CACHE = new Map<string, { rgb: Uint8ClampedArray; aux: Uint8ClampedArray }>();
function peekTexture(id: string): { rgb: Uint8ClampedArray; aux: Uint8ClampedArray } | undefined {
  return TEX_CACHE.get(id);
}
function getTexture(id: string): { rgb: Uint8ClampedArray; aux: Uint8ClampedArray } {
  const hit = TEX_CACHE.get(id);
  if (hit) return hit;
  const t = genTexture(id);
  TEX_CACHE.set(id, t);
  return t;
}

function Closeup(props: { bodyId: string; mode: SpinMode }) {
  const theme = useGrokTheme();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const modeRef = useRef<SpinMode>(props.mode);
  modeRef.current = props.mode;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const v = VIS[props.bodyId];
    if (!v) return;
    const tex = getTexture(props.bodyId);
    const rgb = tex.rgb;
    const aux = tex.aux;
    const isSun = props.bodyId === "sun";
    const isEarth = props.bodyId === "earth";
    const R = v.rfac * CS;
    const D = Math.ceil(R * 2) + 4;
    const half = D / 2;
    const off = document.createElement("canvas");
    off.width = D;
    off.height = D;
    const octx = off.getContext("2d");
    if (!octx) return;
    const img = octx.createImageData(D, D);
    const data = img.data;
    const psi = (v.tilt * Math.PI) / 180;
    const el = (v.elev * Math.PI) / 180;
    const cosP = Math.cos(psi);
    const sinP = Math.sin(psi);
    const cosE = Math.cos(el);
    const sinE = Math.sin(el);
    const ll = Math.hypot(-0.62, 0.38, 0.69);
    const LX = -0.62 / ll;
    const LY = 0.38 / ll;
    const LZ = 0.69 / ll;
    const rimR = v.rim[0];
    const rimG = v.rim[1];
    const rimB = v.rim[2];
    const rimS = v.rim[3];
    const sign = v.rotH < 0 ? -1 : 1;
    const rings = RINGS[props.bodyId];
    const stars = Array.from({ length: 120 }, () => ({
      x: Math.random() * CS,
      y: Math.random() * CS,
      a: 0.2 + Math.random() * 0.7,
    }));
    let raf = 0;
    let last = 0;
    let theta = 0;
    let clock = 0;

    const drawRings = (front: boolean) => {
      if (!rings) return;
      ctx.save();
      ctx.translate(CS / 2, CS / 2);
      ctx.rotate(psi);
      ctx.scale(1, Math.sin(el));
      for (const rg of rings) {
        ctx.beginPath();
        ctx.arc(
          0,
          0,
          ((rg.inner + rg.outer) / 2) * R,
          front ? 0 : Math.PI,
          front ? Math.PI : TAU,
        );
        ctx.strokeStyle = rg.color;
        ctx.lineWidth = (rg.outer - rg.inner) * R;
        ctx.stroke();
      }
      ctx.restore();
    };

    const frame = (now: number) => {
      if (!last) last = now;
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      clock += dt;
      theta += (sign * TAU * dt) / spinSeconds(v.rotH, modeRef.current);
      const thC = theta * 1.08 + clock * 0.02;

      for (let j = 0; j < D; j++) {
        const y0 = -((j + 0.5) - half) / R;
        for (let i = 0; i < D; i++) {
          const x0 = ((i + 0.5) - half) / R;
          const r2 = x0 * x0 + y0 * y0;
          const k = (j * D + i) * 4;
          if (r2 > 1 + 2.2 / R) {
            data[k + 3] = 0;
            continue;
          }
          const rr = Math.sqrt(r2);
          const alpha = clamp((1 - rr) * R + 0.5, 0, 1);
          if (alpha <= 0) {
            data[k + 3] = 0;
            continue;
          }
          let xn = x0;
          let yn = y0;
          let z = 0;
          if (r2 < 1) z = Math.sqrt(1 - r2);
          else {
            xn = x0 / rr;
            yn = y0 / rr;
          }
          const xr = xn * cosP - yn * sinP;
          const yr = xn * sinP + yn * cosP;
          const yb = yr * cosE + z * sinE;
          const zb = -yr * sinE + z * cosE;
          const lat = Math.asin(clamp(yb, -1, 1));
          const la = Math.atan2(xr, zb);
          let u = (la - theta) / TAU + 0.5;
          u -= Math.floor(u);
          const ix = Math.min(TW - 1, Math.floor(u * TW));
          const iy = clamp(Math.floor((0.5 - lat / Math.PI) * TH), 0, TH - 1);
          const idx = iy * TW + ix;
          let cr = rgb[idx * 3];
          let cg = rgb[idx * 3 + 1];
          let cb = rgb[idx * 3 + 2];
          if (isEarth) {
            let uc = (la - thC) / TAU + 0.5;
            uc -= Math.floor(uc);
            const ixc = Math.min(TW - 1, Math.floor(uc * TW));
            const ca = (aux[iy * TW + ixc] / 255) * 0.92;
            cr = cr * (1 - ca) + 250 * ca;
            cg = cg * (1 - ca) + 250 * ca;
            cb = cb * (1 - ca) + 252 * ca;
          }
          if (isSun) {
            const ph = aux[idx] / 255;
            const w = 0.5 + 0.5 * Math.sin(clock * 1.8 + ph * 6.28);
            const fl = 0.86 + 0.28 * (ph * (1 - w) + (1 - ph) * w);
            const ld = 0.35 + 0.65 * Math.pow(z, 0.55);
            cr = cr * fl * ld;
            cg = cg * fl * Math.pow(ld, 1.25);
            cb = cb * fl * Math.pow(ld, 1.7);
          } else {
            const lam = Math.max(0, xn * LX + yn * LY + z * LZ);
            const sh = 0.04 + 0.96 * Math.pow(lam, 0.85);
            const rim = rimS * Math.pow(1 - z, 2.5) * (0.25 + 0.75 * Math.min(1, lam * 1.5));
            cr = cr * sh + rimR * rim;
            cg = cg * sh + rimG * rim;
            cb = cb * sh + rimB * rim;
          }
          data[k] = cr;
          data[k + 1] = cg;
          data[k + 2] = cb;
          data[k + 3] = alpha * 255;
        }
      }
      octx.putImageData(img, 0, 0);

      ctx.fillStyle = "#05070D";
      ctx.fillRect(0, 0, CS, CS);
      for (const s of stars) {
        ctx.fillStyle = `rgba(255,255,255,${s.a * 0.6})`;
        ctx.fillRect(s.x, s.y, 1.3, 1.3);
      }
      if (isSun) {
        const flick = 0.85 + 0.15 * Math.sin(clock * 2.3);
        const gl = ctx.createRadialGradient(CS / 2, CS / 2, R * 0.9, CS / 2, CS / 2, R * 2.4);
        gl.addColorStop(0, `rgba(255,190,70,${0.75 * flick})`);
        gl.addColorStop(0.35, `rgba(255,120,30,${0.28 * flick})`);
        gl.addColorStop(1, "rgba(255,90,20,0)");
        ctx.fillStyle = gl;
        ctx.fillRect(0, 0, CS, CS);
      }
      drawRings(false);
      ctx.drawImage(off, CS / 2 - half, CS / 2 - half);
      drawRings(true);

      ctx.save();
      ctx.translate(CS / 2, CS / 2);
      ctx.rotate(psi);
      ctx.setLineDash([4, 5]);
      ctx.strokeStyle = "rgba(255,255,255,0.35)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, -R * 1.42);
      ctx.lineTo(0, -R * 1.03);
      ctx.moveTo(0, R * 1.03);
      ctx.lineTo(0, R * 1.42);
      ctx.stroke();
      ctx.restore();
      ctx.fillStyle = "rgba(255,255,255,0.65)";
      ctx.font = `600 13px ${theme.font.family}`;
      ctx.textAlign = "center";
      ctx.fillText("N", CS / 2 + sinP * R * 1.52, CS / 2 - cosP * R * 1.52 + 4);

      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [props.bodyId, theme.font.family]);

  return (
    <canvas
      ref={canvasRef}
      width={CS}
      height={CS}
      style={{
        display: "block",
        width: "100%",
        height: "auto",
        borderRadius: theme.radius.lg,
        background: "#05070D",
      }}
    />
  );
}

/* ------------------------------------------------------------------ */
/* 轨道模拟视图                                                        */
/* ------------------------------------------------------------------ */

function SimView(props: {
  playing: boolean;
  speed: Speed;
  showOrbits: boolean;
  showLabels: boolean;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onTime: (years: number) => void;
  resetKey: number;
  simRef: { current: number };
}) {
  const theme = useGrokTheme();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const timeRef = props.simRef;
  const lastRef = useRef(0);
  const playingRef = useRef(props.playing);
  const speedRef = useRef(props.speed);
  const orbitsRef = useRef(props.showOrbits);
  const labelsRef = useRef(props.showLabels);
  const selectedRef = useRef(props.selectedId);
  const starsRef = useRef<{ x: number; y: number; a: number }[]>([]);

  playingRef.current = props.playing;
  speedRef.current = props.speed;
  orbitsRef.current = props.showOrbits;
  labelsRef.current = props.showLabels;
  selectedRef.current = props.selectedId;
  const onTimeRef = useRef(props.onTime);
  onTimeRef.current = props.onTime;
  const lastReport = useRef(0);
  useEffect(() => {
    props.onTime(timeRef.current);
  }, [props.resetKey]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;
    let w = 0;
    let h = 0;
    let dpr = 1;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = Math.max(wrap.clientWidth, 320);
      h = Math.max(Math.round(w * 0.72), 360);
      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const count = Math.floor((w * h) / 2800);
      const stars: { x: number; y: number; a: number }[] = [];
      for (let i = 0; i < count; i++) {
        stars.push({
          x: Math.random() * w,
          y: Math.random() * h,
          a: 0.25 + Math.random() * 0.75,
        });
      }
      starsRef.current = stars;
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(wrap);

    const draw = (now: number) => {
      if (!lastRef.current) lastRef.current = now;
      const dt = Math.min((now - lastRef.current) / 1000, 0.05);
      lastRef.current = now;

      if (playingRef.current) {
        timeRef.current += (dt * Number(speedRef.current)) / YEAR_S;
      }
      if (now - lastReport.current > 200) {
        lastReport.current = now;
        onTimeRef.current(timeRef.current);
      }

      const t = timeRef.current;
      const cx = w / 2;
      const cy = h / 2;
      const scale = Math.min(w, h) / 720;

      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = theme.kind === "dark" ? "#05070D" : "#0B1020";
      ctx.fillRect(0, 0, w, h);

      for (const s of starsRef.current) {
        ctx.fillStyle = `rgba(255,255,255,${s.a * 0.55})`;
        ctx.fillRect(s.x, s.y, 1.2, 1.2);
      }

      if (orbitsRef.current) {
        ctx.strokeStyle =
          theme.kind === "dark"
            ? "rgba(255,255,255,0.12)"
            : "rgba(255,255,255,0.18)";
        ctx.lineWidth = 1;
        for (const b of BODIES) {
          ctx.beginPath();
          ctx.arc(cx, cy, b.orbit * scale, 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      const sunR = 18 * scale;
      const sunGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, sunR * 2.2);
      sunGrad.addColorStop(0, "#FFF4C2");
      sunGrad.addColorStop(0.35, "#F5C542");
      sunGrad.addColorStop(0.7, "rgba(245,140,40,0.55)");
      sunGrad.addColorStop(1, "rgba(245,100,20,0)");
      ctx.fillStyle = sunGrad;
      ctx.beginPath();
      ctx.arc(cx, cy, sunR * 2.2, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#FFD56A";
      ctx.beginPath();
      ctx.arc(cx, cy, sunR, 0, Math.PI * 2);
      ctx.fill();

      if (selectedRef.current === "sun") {
        ctx.strokeStyle = "rgba(255,255,255,0.75)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(cx, cy, sunR + 6 * scale, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (labelsRef.current) {
        ctx.fillStyle = "rgba(255,255,255,0.85)";
        ctx.font = `600 ${Math.max(11, 12 * scale)}px ${theme.font.family}`;
        ctx.textAlign = "center";
        ctx.fillText("太阳", cx, cy + sunR + 14 * scale);
      }

      for (const b of BODIES) {
        const angle = -helioLon(b.id, t);
        const ox = cx + Math.cos(angle) * b.orbit * scale;
        const oy = cy + Math.sin(angle) * b.orbit * scale;
        const r = b.radius * scale;
        const selected = selectedRef.current === b.id;

        if (selected) {
          ctx.strokeStyle = "rgba(255,255,255,0.75)";
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(ox, oy, r + 5 * scale, 0, Math.PI * 2);
          ctx.stroke();
        }

        if (b.id === "saturn") {
          ctx.strokeStyle = "rgba(232,213,163,0.65)";
          ctx.lineWidth = Math.max(1.5, 2.5 * scale);
          ctx.beginPath();
          ctx.ellipse(ox, oy, r * 1.9, r * 0.55, -0.4, 0, Math.PI * 2);
          ctx.stroke();
        }

        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(ox, oy, r, 0, Math.PI * 2);
        ctx.fill();

        if (b.id === "earth") {
          ctx.fillStyle = "rgba(90,180,90,0.55)";
          ctx.beginPath();
          ctx.arc(ox - r * 0.2, oy, r * 0.45, 0, Math.PI * 2);
          ctx.fill();
        }

        if (labelsRef.current) {
          ctx.fillStyle = "rgba(255,255,255,0.9)";
          ctx.font = `500 ${Math.max(10, 11 * scale)}px ${theme.font.family}`;
          ctx.textAlign = "left";
          ctx.fillText(b.name, ox + r + 4 * scale, oy + 3);
        }
      }

      raf = requestAnimationFrame(draw);
    };

    raf = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
    };
  }, [theme.kind, theme.font.family]);

  const onPointer = useCallback(
    (clientX: number, clientY: number) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const w = rect.width;
      const h = rect.height;
      const cx = w / 2;
      const cy = h / 2;
      const scale = Math.min(w, h) / 720;
      const t = timeRef.current;

      let hit: string | null = null;
      const sunHit = Math.max(18 * scale, 12) + 8;
      if ((x - cx) * (x - cx) + (y - cy) * (y - cy) <= sunHit * sunHit) {
        hit = "sun";
      } else {
        for (let i = BODIES.length - 1; i >= 0; i--) {
          const b = BODIES[i];
          const angle = -helioLon(b.id, t);
          const ox = cx + Math.cos(angle) * b.orbit * scale;
          const oy = cy + Math.sin(angle) * b.orbit * scale;
          const r = Math.max(b.radius * scale, 10);
          const dx = x - ox;
          const dy = y - oy;
          if (dx * dx + dy * dy <= (r + 6) * (r + 6)) {
            hit = b.id;
            break;
          }
        }
      }
      props.onSelect(hit === props.selectedId ? null : hit);
    },
    [props],
  );

  return (
    <div
      ref={wrapRef}
      style={{
        width: "100%",
        borderRadius: theme.radius.xl,
        overflow: "hidden",
        border: `1px solid ${theme.border.default}`,
        background: theme.bg.base,
      }}
    >
      <canvas
        ref={canvasRef}
        onClick={(e) => onPointer(e.clientX, e.clientY)}
        style={{ display: "block", width: "100%", cursor: "pointer" }}
      />
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* 页面                                                                */
/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/* 3D 场景：自写透视投影 + 球体活动精灵渲染                                */
/* ------------------------------------------------------------------ */

type V3 = [number, number, number];
const vdot = (a: V3, b: V3): number => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const vsub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const vadd = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const vscl = (a: V3, k: number): V3 => [a[0] * k, a[1] * k, a[2] * k];
const vcross = (a: V3, b: V3): V3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const vlen = (a: V3): number => Math.hypot(a[0], a[1], a[2]);
const vnorm = (a: V3): V3 => {
  const l = vlen(a) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};
const D2R = Math.PI / 180;
const ORIGIN: V3 = [0, 0, 0];

function rotOrbit(x: number, y: number, I: number, om: number, Om: number): V3 {
  const cI = Math.cos(I);
  const sI = Math.sin(I);
  const co = Math.cos(om);
  const so = Math.sin(om);
  const cO = Math.cos(Om);
  const sO = Math.sin(Om);
  return [
    (co * cO - so * sO * cI) * x + (-so * cO - co * sO * cI) * y,
    (co * sO + so * cO * cI) * x + (-so * sO + co * cO * cI) * y,
    so * sI * x + co * sI * y,
  ];
}
function orbElems(id: string, T: number) {
  const el = ELEMENTS[id];
  const Omd = el[10] + el[11] * T;
  const w = el[8] + el[9] * T;
  return {
    a: el[0] + el[1] * T,
    e: el[2] + el[3] * T,
    I: (el[4] + el[5] * T) * D2R,
    L: el[6] + el[7] * T,
    w,
    Om: Omd * D2R,
    om: (w - Omd) * D2R,
  };
}
// 日心黄道坐标（AU，J2000 黄道，X = 春分点，Z = 黄道北极）
function helioVec(id: string, years: number): V3 {
  const T = (JD_START + years * 365.25 - 2451545.0) / 36525;
  const q = orbElems(id, T);
  const M = (((((q.L - q.w) % 360) + 540) % 360) - 180) * D2R;
  let E = M + q.e * Math.sin(M);
  for (let i = 0; i < 12; i++) {
    E += (M - (E - q.e * Math.sin(E))) / (1 - q.e * Math.cos(E));
  }
  return rotOrbit(q.a * (Math.cos(E) - q.e), q.a * Math.sqrt(1 - q.e * q.e) * Math.sin(E), q.I, q.om, q.Om);
}
function orbitPoints(id: string, n: number): V3[] {
  const T = (JD_START - 2451545.0) / 36525;
  const q = orbElems(id, T);
  const pts: V3[] = [];
  for (let i = 0; i < n; i++) {
    const E = (i / n) * Math.PI * 2;
    pts.push(toScene(rotOrbit(q.a * (Math.cos(E) - q.e), q.a * Math.sqrt(1 - q.e * q.e) * Math.sin(E), q.I, q.om, q.Om)));
  }
  return pts;
}
// 距离压缩（方向、黄纬不变）
const cmpR = (r: number): number => 46 * Math.pow(r, 0.58);
function toScene(v: V3): V3 {
  const r = vlen(v) || 1;
  return vscl(v, cmpR(r) / r);
}

// 简化月球理论（Meeus 主要项），转换到 J2000 黄道，返回弧度与公里
function moonState(jd: number): { lon: number; lat: number; dist: number } {
  const T = (jd - 2451545.0) / 36525;
  const S = (x: number) => Math.sin(x * D2R);
  const C = (x: number) => Math.cos(x * D2R);
  const Lp = 218.3164477 + 481267.88123421 * T;
  const D = 297.8501921 + 445267.1114034 * T;
  const Ms = 357.5291092 + 35999.0502909 * T;
  const Mp = 134.9633964 + 477198.8675055 * T;
  const F = 93.272095 + 483202.0175233 * T;
  const lon =
    Lp + 6.288774 * S(Mp) + 1.274027 * S(2 * D - Mp) + 0.658314 * S(2 * D) + 0.213618 * S(2 * Mp) -
    0.185116 * S(Ms) - 0.114332 * S(2 * F) + 0.058793 * S(2 * D - 2 * Mp) + 0.057066 * S(2 * D - Ms - Mp) +
    0.053322 * S(2 * D + Mp) + 0.045758 * S(2 * D - Ms) - 1.3969 * T;
  const lat =
    5.128122 * S(F) + 0.280602 * S(Mp + F) + 0.277693 * S(Mp - F) + 0.173237 * S(2 * D - F) +
    0.055413 * S(2 * D - Mp + F) + 0.046271 * S(2 * D - Mp - F);
  const dist =
    385000.56 - 20905.355 * C(Mp) - 3699.111 * C(2 * D - Mp) - 2955.968 * C(2 * D) - 569.925 * C(2 * Mp) +
    48.888 * C(Ms) - 3.149 * C(2 * F) + 246.158 * C(2 * D - 2 * Mp) - 152.138 * C(2 * D - Ms - Mp) -
    170.733 * C(2 * D + Mp) - 204.586 * C(2 * D - Ms);
  return { lon: lon * D2R, lat: lat * D2R, dist };
}
const MOON_DISP_DIST = 10.5;
function moonOffset(jd: number): V3 {
  const m = moonState(jd);
  const k = (MOON_DISP_DIST * m.dist) / 384400;
  return [Math.cos(m.lat) * Math.cos(m.lon) * k, Math.cos(m.lat) * Math.sin(m.lon) * k, Math.sin(m.lat) * k];
}

const POLE_RADEC: Record<string, [number, number]> = {
  sun: [286.13, 63.87],
  mercury: [281.01, 61.414],
  venus: [272.76, 67.16],
  earth: [0, 90],
  mars: [317.681, 52.887],
  jupiter: [268.057, 64.495],
  saturn: [40.589, 83.537],
  uranus: [257.311, -15.175],
  // PREV neptune [299.36, 43.46]（J2000 值，未含进动项；IAU pck00011 在 2026 年为 299.504, 42.961）
  neptune: [299.504, 42.961],
  // PREV ceres [291.0, 67.0]
  ceres: [291.418, 66.764],
  pluto: [132.99, -6.16],
};
function poleOf(id: string): V3 {
  const p = POLE_RADEC[id];
  if (!p) return [0, 0, 1];
  const ra = p[0] * D2R;
  const dec = p[1] * D2R;
  const xe = Math.cos(dec) * Math.cos(ra);
  const ye = Math.cos(dec) * Math.sin(ra);
  const ze = Math.sin(dec);
  const eps = 23.43928 * D2R;
  return vnorm([xe, ye * Math.cos(eps) + ze * Math.sin(eps), -ye * Math.sin(eps) + ze * Math.cos(eps)]);
}
function basisOf(A: V3): { e1: V3; e2: V3; A: V3 } {
  const ref: V3 = Math.abs(A[0]) > 0.95 ? [0, 1, 0] : [1, 0, 0];
  const e1 = vnorm(vsub(ref, vscl(A, vdot(ref, A))));
  return { e1, e2: vcross(A, e1), A };
}
const BASES: Record<string, { e1: V3; e2: V3; A: V3 }> = {};
for (const id of ["sun", "mercury", "venus", "earth", "moon", "mars", "jupiter", "saturn", "uranus", "neptune", "ceres", "pluto"]) {
  BASES[id] = basisOf(poleOf(id));
}

