/**
 * Menu planet tap for bodies with moons (Earth/Jupiter/…):
 *  1st → system panoramic overview (FD2[0], bare id)
 *  2nd while already in that overview → primary close-up (id:close)
 * From a moon of this parent → back to system overview first.
 * From primary close-up → stay/re-assert close-up (caller closes UI).
 * Moonless planets just use bare id once (caller closes UI).
 */
function focusPlanetMenuTarget(current: string, bodyId: string): string {
  if (bodyId === "overview") return "overview";
  const curId = current.split(":")[0];
  const hasMoons = !!(FOCUS_MOONS[bodyId] && FOCUS_MOONS[bodyId].length);
  if (!hasMoons) return bodyId;
  // On one of this body's moons → parent system panorama
  if (MOON_TO_PARENT[curId] === bodyId) return bodyId;
  // Already at system overview (bare id or :system alias) → primary close-up
  if (curId === bodyId && current !== `${bodyId}:close`) return `${bodyId}:close`;
  // Already at primary close-up → keep close-up
  if (current === `${bodyId}:close`) return `${bodyId}:close`;
  // From elsewhere → system panorama
  return bodyId;
}
