function eclFromEq(raDeg: number, decDeg: number): V3 {
  const ra = raDeg * D2R;
  const dec = decDeg * D2R;
  const xe = Math.cos(dec) * Math.cos(ra);
  const ye = Math.cos(dec) * Math.sin(ra);
  const ze = Math.sin(dec);
  const eps = 23.43928 * D2R;
  return vnorm([xe, ye * Math.cos(eps) + ze * Math.sin(eps), -ye * Math.sin(eps) + ze * Math.cos(eps)]);
}
const GAL_X = eclFromEq(266.405, -28.936);
const GAL_Z = eclFromEq(192.8595, 27.1283);
const GAL_Y = vcross(GAL_Z, GAL_X);
const JUP_NODE = eclFromEq(268.057 + 90, 0);
/* ===== t145：自转相位（IAU WGCCRE / NAIF pck00011）与卫星轨道模型 ===== */
// 本初子午线角 W = W0 + Wd·d（°，°/天，d 自 J2000 起算，TDB）；Wd>0 = 绕 IAU 北极右手系自转。
// PREV: 自转相位只由 VIS.rotH 给周期、没有 W0，所以各天体的“0° 经线”朝向是任意的。
// t152 Io: IAU rotation (WGCCRE) pole RA 268.05 / Dec 64.50, W = 200.39 + 203.4889538·d. NOT added to ROT_IAU on purpose:
//   Io is tidally locked in MOON_LIST (lockPoleOf/lockOffOf, off=-0.391) so its 0° meridian already faces Jupiter and map east-lon = IAU east-lon.
//   Adding `io: [200.39, 203.4889538]` here would crash the ROT_PHI0 loop (Io has no POLE_RADEC/BASES entry). PREV: unchanged.
const ROT_IAU: Record<string, [number, number]> = {
  sun: [84.176, 14.1844],
  mercury: [329.5988, 6.1385108],
  venus: [160.2, -1.4813688],
  // IAU2015 的 Mars W 含一个周期约 714 年的长周期项（2026 年附近约 +0.55°），已折进 W0（PREV 176.049863）
  mars: [176.6029, 350.891982443297],
  jupiter: [284.95, 870.536],
  saturn: [38.9, 810.7939024],
  uranus: [203.81, -501.1600928],
  neptune: [249.978, 541.1397757],
  ceres: [170.65, 952.1532],
  pluto: [302.695, 56.3625225],
};
const ROT_DT_DAYS = 69.184 / 86400; // TDB − UT（2026）
// IAU 的 W 从「赤道升交点（赤经 α0+90°）」量起；换算到 BASES 的 e1/e2 基底的起算角
const ROT_PHI0: Record<string, number> = {};
for (const id of Object.keys(ROT_IAU)) {
  const nodeV = eclFromEq(POLE_RADEC[id][0] + 90, 0);
  ROT_PHI0[id] = Math.atan2(vdot(nodeV, BASES[id].e2), vdot(nodeV, BASES[id].e1)) / D2R;
}
function spinW(id: string, jd: number): number {
  const r = ROT_IAU[id];
  if (!r) return 0;
  const w = r[0] + r[1] * (jd - 2451545.0 + ROT_DT_DAYS) + ROT_PHI0[id];
  return ((((w % 360) + 360) % 360) * Math.PI) / 180;
}
function spinSign(id: string): number {
  const r = ROT_IAU[id];
  return r && r[1] < 0 ? -1 : 1;
}
// 月球自转极：Cassini 态，与黄极夹角 1.5424°，方向与月球轨道法向相反；随升交点（周期 18.6 年）旋转
// PREV: 月球极 = 黄极 [0,0,1]（偏 1.5°）
function moonPoleAt(jd: number): V3 {
  const T = (jd - 2451545.0) / 36525;
  const Om = (125.0445479 - 1934.1362891 * T + 0.0020754 * T * T) * D2R;
  const tl = 1.5424 * D2R;
  return [-Math.sin(tl) * Math.sin(Om), Math.sin(tl) * Math.cos(Om), Math.cos(tl)];
}
// 母行星赤道系（拟合所用：N = 赤道升交点方向，A = 极，E = A×N）
const MOON_PARENT_POLE: Record<string, [number, number]> = {
  jupiter: [268.057, 64.495],
  saturn: [40.589, 83.537],
  uranus: [257.311, -15.175],
  neptune: [299.36, 43.46],
  pluto: [132.99, -6.16],
};
const MOON_FRAMES: Record<string, { N: V3; E: V3; A: V3 }> = {};
for (const pid of Object.keys(MOON_PARENT_POLE)) {
  const pp = MOON_PARENT_POLE[pid];
  const pA = eclFromEq(pp[0], pp[1]);
  let pN = eclFromEq(pp[0] + 90, 0);
  pN = vnorm(vsub(pN, vscl(pA, vdot(pN, pA))));
  MOON_FRAMES[pid] = { N: pN, E: vcross(pA, pN), A: pA };
}
function kepE(M: number, e: number): number {
  let E = M + e * Math.sin(M);
  for (let i = 0; i < 12; i++) E += (M - (E - e * Math.sin(E))) / (1 - e * Math.cos(E));
  return E;
}
// 卫星相对母行星的位置（km，日心黄道系轴向）
function moonRelAt(gm: MoonOrb, jd: number): V3 {
  const t = jd - 2451545.0;
  const f = MOON_FRAMES[gm.parent];
  const Om = (gm.Om + gm.dOm * t) * D2R;
  const vp = (gm.vp + gm.dvp * t) * D2R;
  const Lm = (gm.L0 + gm.rate * t) * D2R;
  const M = ((((Lm - vp) % TAU) + 3 * Math.PI) % TAU) - Math.PI;
  const E = kepE(M, gm.e);
  const q = rotOrbit(gm.a * (Math.cos(E) - gm.e), gm.a * Math.sqrt(1 - gm.e * gm.e) * Math.sin(E), gm.I * D2R, vp - Om, Om);
  return vadd(vadd(vscl(f.N, q[0]), vscl(f.E, q[1])), vscl(f.A, q[2]));
}
function moonOrbitNormal(gm: MoonOrb, jd: number): V3 {
  const t = jd - 2451545.0;
  const f = MOON_FRAMES[gm.parent];
  const Om = (gm.Om + gm.dOm * t) * D2R;
  const I = gm.I * D2R;
  return vadd(vadd(vscl(f.N, Math.sin(I) * Math.sin(Om)), vscl(f.E, -Math.sin(I) * Math.cos(Om))), vscl(f.A, Math.cos(I)));
}
// 潮汐锁定天体的 IAU 北极（Triton、Titania 的 IAU 极与轨道角动量反向 = 逆行/倾卧轨道）
function lockPoleOf(id: string, jd: number): V3 {
  if (id === "moon") return moonPoleAt(jd);
  if (id === "triton") return vscl(moonOrbitNormal(NEP2[0], jd), -1); // PREV: BASES.neptune.A
  if (id === "titania") return MOON_FRAMES.uranus.A; // = 天王星极；PREV: BASES.uranus.A（轨道方向误为顺行）
  const gm = MOON_LIST.find((g) => g.id === id);
  if (gm) return MOON_FRAMES[gm.parent].A;
  return BASES[id] ? BASES[id].A : [0, 0, 1];
}
function lockOffOf(id: string): number {
  if (id === "pluto") return 1.504; // 冥王星上「朝向卡戎」的平均经度（IAU 系，°）
  const gm = MOON_LIST.find((g) => g.id === id);
  return gm ? gm.off : 0;
}

const UPW: V3 = [0, 0, 1];

function makeStars(): { d: V3; m: number; c: number }[] {
  let s = 20261102;
  const rnd = () => {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
  const out: { d: V3; m: number; c: number }[] = [];
  for (let i = 0; i < 2600; i++) {
    let d: V3;
    if (rnd() < 0.55) {
      const l = rnd() * TAU;
      const b = (rnd() + rnd() + rnd() - 1.5) * 0.28;
      d = vadd(vadd(vscl(GAL_X, Math.cos(b) * Math.cos(l)), vscl(GAL_Y, Math.cos(b) * Math.sin(l))), vscl(GAL_Z, Math.sin(b)));
    } else {
      const z = rnd() * 2 - 1;
      const a = rnd() * TAU;
      const r = Math.sqrt(1 - z * z);
      d = [r * Math.cos(a), r * Math.sin(a), z];
    }
    const m = Math.pow(rnd(), 3.2);
    out.push({ d: vnorm(d), m, c: rnd() });
  }
  return out;
}
const STARS = makeStars();

/* 小行星带 / 柯伊伯带：廉价视觉点（非独立球体），仅作背景 */
type BeltPt = { a: number; e: number; I: number; Om: number; M0: number; sz: number; bri: number };
function makeBelt(count: number, a0: number, a1: number, iMaxDeg: number, seed0: number, sizeBase: number): BeltPt[] {
  let s = seed0;
  const rnd = () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  };
  const out: BeltPt[] = [];
  for (let i = 0; i < count; i++) {
    const u = rnd();
    const a = a0 + (a1 - a0) * (u * u * 0.35 + u * 0.65);
    out.push({
      a,
      e: 0.01 + rnd() * 0.12,
      I: ((rnd() + rnd() + rnd()) / 3 - 0.5) * 2 * iMaxDeg * D2R,
      Om: rnd() * TAU,
      M0: rnd() * TAU,
      sz: sizeBase * (0.55 + rnd() * 0.9),
      bri: 0.25 + rnd() * 0.75,
    });
  }
  return out;
}
const AST_BELT = makeBelt(2000, 2.15, 3.3, 18, 424242, 1.15);
const KUIPER_BELT = makeBelt(3000, 30.5, 48.0, 22, 777001, 0.95);
function beltPosKm(pt: BeltPt, years: number): V3 {
  /* 视觉环带：用平近点角直接铺点，避免每帧开普勒迭代 */
  const M = pt.M0 + (TAU * years) / Math.pow(pt.a, 1.5);
  const r = pt.a * (1 - pt.e * Math.cos(M));
  const x = r * Math.cos(M);
  const y = r * Math.sin(M);
  const cO = Math.cos(pt.Om);
  const sO = Math.sin(pt.Om);
  const cI = Math.cos(pt.I);
  const sI = Math.sin(pt.I);
  return [(cO * x - sO * cI * y) * AU_KM, (sO * x + cO * cI * y) * AU_KM, sI * y * AU_KM];
}

const ORB_OFFS: number[] = (() => {
  const a: number[] = [];
  for (let i = 0; i < 60; i++) a.push(Math.exp(Math.log(2e-5) + (Math.log(0.12) - Math.log(2e-5)) * (i / 59)));
  for (let k = 1; k <= 100; k++) a.push((k * Math.PI) / 100);
  a.sort((x, y) => x - y);
  return a;
})();
function planetOrbitKm(id: string, years: number): V3[] {
  const T = (JD_START + years * 365.25 - 2451545.0) / 36525;
  const q = orbElems(id, T);
  const M = (((((q.L - q.w) % 360) + 540) % 360) - 180) * D2R;
  let E = M + q.e * Math.sin(M);
  for (let i = 0; i < 12; i++) E += (M - (E - q.e * Math.sin(E))) / (1 - q.e * Math.cos(E));
  const b = q.a * Math.sqrt(1 - q.e * q.e);
  const pt = (e: number): V3 => vscl(rotOrbit(q.a * (Math.cos(e) - q.e), b * Math.sin(e), q.I, q.om, q.Om), AU_KM);
  const out: V3[] = [];
  for (let i = ORB_OFFS.length - 1; i >= 0; i--) out.push(pt(E - ORB_OFFS[i]));
  out.push(pt(E));
  for (let i = 0; i < ORB_OFFS.length; i++) out.push(pt(E + ORB_OFFS[i]));
  return out;
}
function moonVec(jd: number): V3 {
  const m = moonState(jd);
  return [Math.cos(m.lat) * Math.cos(m.lon) * m.dist, Math.cos(m.lat) * Math.sin(m.lon) * m.dist, Math.sin(m.lat) * m.dist];
}

function fmtLen(km: number): string {
  if (km >= 1.5e7) {
    const au = km / AU_KM;
    return `${au.toFixed(au >= 10 ? 1 : 2)} AU`;
  }
  if (km >= 1e6) return `${(km / 1e6).toFixed(2)} 百万公里`;
  if (km >= 1e4) return `${(km / 1e4).toFixed(1)} 万公里`;
  return `${Math.round(km).toLocaleString("en-US")} 公里`;
}

